contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, uint value) public payable {
        require(caller != address(this), "test cannot impersonate itself");
        require(address(this).balance >= value, "insufficient test balance");

        c.withdrawAll();

        bool reverted;
        if (caller == address(this)) {
            c.withdrawAll();
            reverted = false;
        } else {
            (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            reverted = !ok;
        }

        assert(!reverted);

        address target = address(0x1234567890123456789012345678901234567890);
        c.sendMoney{value: value}(target, value);
        assert(address(c).balance == address(this).balance - value || address(c).balance == 0);
    }

    receive() external payable {}
}

