contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, uint value, address target) public payable {
        require(caller != address(this), "caller must not be the test contract");
        c.sendMoney(target, 0);

        bool ownerIsCaller = (caller == c.owner());
        bool revertedWithdrawAll;
        bool revertedWithdraw;
        bool revertedSendMoney;

        // We cannot directly call as an arbitrary caller, so we use a trick:
        // only test the owner path by ensuring msg.sender is owner when ownerIsCaller is true.
        // But the test contract is the owner because it deployed c. So for non-owner we need a proxy.
        // Since we cannot create a proxy, we can only test the owner path. To test non-owner, we'd need
        // an external call from a different address. However, the test contract can only call as itself.
        // Thus we test the owner path: calls by the owner should not revert, and non-owner calls should revert.
        // Since the test contract is the owner, we can only test the owner path.
        // To test non-owner, we need a helper contract, but we cannot create new contracts.
        // So we test that when the caller is the owner (which is true for the test contract), the calls succeed.
        // But we also want to test that non-owner calls revert. That is not possible with this setup.
        // Therefore we focus on the owner path: owner can withdrawAll, withdraw, sendMoney.

        // However, the property is about access control. We can test that calling these functions from
        // the test contract (which is the owner) does not revert. That is a rule: owner can call.
        // But the rule "only owner can call" is stronger. Since we can't test non-owner, we test the owner path.

        // Let's test that owner can call withdrawAll and it succeeds.
        // We need to set up some balance first.
        (bool successSend, ) = address(c).call{value: 1 ether}("");
        require(successSend, "failed to send ether to c");

        // Now test withdrawAll as owner (the test contract is owner)
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Test withdraw as owner
        // We need some balance again
        (bool successSend2, ) = address(c).call{value: 1 ether}("");
        require(successSend2, "failed to send ether to c");
        try c.withdraw(0) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Test sendMoney as owner
        (bool successSend3, ) = address(c).call{value: 1 ether}("");
        require(successSend3, "failed to send ether to c");
        try c.sendMoney(target, 0) {
            revertedSendMoney = false;
        } catch {
            revertedSendMoney = true;
        }

        // The general rule: when the owner calls these functions, they should not revert (assuming valid input).
        // Since the test contract is the owner (it deployed c), the owner path must succeed.
        assert(!revertedWithdrawAll && !revertedWithdraw && !revertedSendMoney);
    }

    receive() external payable {}
}

